mapper.update:
UPDATE business_card_import_request
SET request_fingerprint = #{requestFingerprint},
  expires_at = #{expiresAt},
  submission_expires_at = NULL,
  reservation_slot = NULL
WHERE workspace_id = #{workspaceId}
  AND idempotency_key = #{idempotencyKey}
  AND request_fingerprint IS NULL
  AND created_by_user_id = #{userId}
  AND submission_expires_at > #{now}
  AND expires_at > #{now}

UPDATE business_card_import_request
SET submission_expires_at = #{submissionExpiresAt},
  created_by_user_id = #{userId}
WHERE workspace_id = #{workspaceId}
  AND idempotency_key = #{idempotencyKey}
  AND request_fingerprint IS NULL
  AND created_by_user_id = #{userId}
  AND reservation_slot IS NOT NULL
  AND expires_at > #{now}

mapper.delete:
DELETE FROM business_card_import_request
WHERE workspace_id = #{workspaceId}
  AND created_by_user_id = #{userId}
  AND request_fingerprint IS NULL
  AND submission_expires_at <= #{now}

DELETE FROM business_card_import_request
WHERE workspace_id = #{workspaceId}
  AND expires_at <= #{cutoff}
ORDER BY expires_at, idempotency_key
LIMIT #{limit}

mapper.select:
SELECT workspace_id
FROM business_card_import_request
WHERE expires_at <= #{cutoff}
GROUP BY workspace_id
ORDER BY MIN(expires_at), workspace_id
LIMIT #{limit}
